mkdir -p /tmp/gatetest && cat > /tmp/gatetest/t.mjs <<'EOF'
import assert from 'node:assert/strict';
import { createGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/baseline-d2-2/bot.mjs';
const D = (s) => new Date(s);
const LA = 'America/Los_Angeles', BE = 'Europe/Berlin';
const r = (g, o) => g.request({ userId: 'u', timeZone: LA, category: 'promo', ...o });

// cap 3 per local day, gap 2h
let g = createGate();
assert.equal(r(g, { now: D('2026-10-21T15:00:00Z') }).allowed, true);  // 08:00 PDT
let x = r(g, { now: D('2026-10-21T16:59:59Z') });
assert.deepEqual(x, { allowed: false, rule: 'min-gap', id: null });
assert.equal(r(g, { now: D('2026-10-21T17:00:00Z') }).allowed, true);  // exactly 2h
assert.equal(r(g, { now: D('2026-10-21T19:00:00Z') }).allowed, true);
assert.equal(r(g, { now: D('2026-10-21T21:00:00Z') }).rule, 'daily-cap');
// local midnight PDT = 07:00Z; 06:59Z still Oct 21 local... new day at 07:00Z Oct 22
assert.equal(r(g, { now: D('2026-10-22T06:59:00Z') }).rule, 'daily-cap');
assert.equal(r(g, { now: D('2026-10-22T07:00:00Z') }).allowed, true);

// other users independent; security unaffected and not counted
g = createGate();
for (const h of [0, 2, 4]) assert.equal(r(g, { now: D(`2026-10-21T${15 + h}:00:00Z`) }).allowed, true);
const s = g.request({ userId: 'u', timeZone: LA, category: 'security', now: D('2026-10-21T19:01:00Z') });
assert.equal(s.allowed, true); assert.equal(s.rule, '');
assert.equal(g.request({ userId: 'v', timeZone: LA, category: 'promo', now: D('2026-10-21T19:01:00Z') }).allowed, true);

// security does not consume gap/cap
g = createGate();
g.request({ userId: 'u', timeZone: LA, category: 'security', now: D('2026-10-21T15:00:00Z') });
assert.equal(r(g, { now: D('2026-10-21T15:01:00Z') }).allowed, true);

// cancel frees slot and gap; idempotent
g = createGate();
const a = r(g, { now: D('2026-10-21T15:00:00Z') });
assert.equal(r(g, { now: D('2026-10-21T15:30:00Z') }).rule, 'min-gap');
g.cancel(a.id); g.cancel(a.id); g.cancel('nope');
assert.equal(r(g, { now: D('2026-10-21T15:30:00Z') }).allowed, true);
const ids = new Set();
g = createGate();
for (let i = 0; i < 3; i++) ids.add(r(g, { now: D(`2026-10-21T${String(8 + i * 3).padStart(2, '0')}:00:00Z`), timeZone: BE }).id);
assert.equal(ids.size, 3);
g.cancel([...ids][0]);
assert.equal(g.request({ userId: 'u', timeZone: BE, category: 'promo', now: D('2026-10-21T20:00:00Z') }).allowed, true);

// Berlin midnight: 22:00Z Oct 21 = 00:00 Oct 22 CEST
g = createGate();
for (const t of ['2026-10-21T19:00:00Z', '2026-10-21T21:00:00Z']) g.request({ userId: 'u', timeZone: BE, category: 'promo', now: D(t) });
assert.equal(g.request({ userId: 'u', timeZone: BE, category: 'promo', now: D('2026-10-21T21:59:00Z') }).rule, 'min-gap'.replace('min-gap','min-gap'));
// DST end Berlin 2026-10-25 (25h day): three allowed, 4th denied
g = createGate();
const b = (t) => g.request({ userId: 'u', timeZone: BE, category: 'promo', now: D(t) });
assert.equal(b('2026-10-24T22:00:00Z').allowed, true); // 00:00 Oct 25 CEST
assert.equal(b('2026-10-25T00:00:00Z').allowed, true);
assert.equal(b('2026-10-25T02:00:00Z').allowed, true);
assert.equal(b('2026-10-25T04:00:00Z').rule, 'daily-cap');
assert.equal(b('2026-10-25T22:59:00Z').rule, 'daily-cap'); // 23:59 CET still Oct 25
assert.equal(b('2026-10-25T23:00:00Z').allowed, true);

// bad input
assert.equal(r(createGate(), { timeZone: 'Nope/Zone', now: D('2026-10-21T15:00:00Z') }).allowed, false);
assert.equal(r(createGate(), { now: new Date('x') }).allowed, false);
console.log('ok');
EOF
cd /tmp && node /tmp/gatetest/t.mjs
